vec3 palette( float t )
{
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.263, 0.416, 0.557);

    return a + b * cos(6.28318 * (c * t + d));
}
float fractal(vec3 p, out vec3 rgb, int iterations){
  float m = 1.;

  for (int i = 0; i < iterations; i++) {
    float n = abs(p.x*p.y*p.z);
    p = abs(p)/clamp(n,.325,1.35)-1.85;
     p.y+=0.2*sin(iTime);
p.x+=0.2*cos(iTime);
    m = abs(min(p.x,min(p.y,p.z)));
  }
  m = exp(-2. * m)*5.;
  rgb=vec3(p.xy,1.0) * m;
  return length(rgb);
}
float happy_star(vec2 uv3, float anim)
{
    uv3 = abs(uv3);
    vec2 pos = min(uv3.xy/uv3.yx, anim);
    float p = (2.0 - pos.x - pos.y);
    return (2.0+p*(p*p-1.5)) / (uv3.x+uv3.y);      
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;
    vec2 uv0 = uv;
    vec3 finalColor = vec3(0.0);
     vec2 uv4 = ( fragCoord - .5*iResolution.xy ) / iResolution.y;
     vec2 xy = fragCoord.xy; 

    vec3 frac = vec3(0, 0, 0);

    if (xy.x >= (iResolution.x / 2.0+cos(iTime) - (iResolution.y) / 2.0) && xy.x <= (iResolution.x / 2.0 + (iResolution.y) / 2.0)) {
        frac = vec3(1, 1, 1);
    }

    float val = 1.0;

    float x_border = (iResolution.x / 2.0 - (iResolution.y) / 2.0);

    float xCur = iResolution.y;
    float yCur = iResolution.y;
    float x_border_cur = x_border;
    float y_border_cur = 0.0;

    for(float i = 0.0; i < 5.0; i += 1.0) {
        xCur = xCur / 3.0;
        yCur = yCur / 3.0;
        x_border_cur = xCur * 3.0;
        y_border_cur = yCur * 3.0;

       for (float j = 0.0; j < pow(3.0, i); j += 1.0) {
           for (float g = 0.0; g < pow(3.0, i); g += 1.0) {
               if ((xy.x >= x_border + x_border_cur * g + xCur && xy.x <= x_border + x_border_cur * g + xCur * 2.0+cos(iTime)) && (xy.y >= yCur + y_border_cur * j && xy.y <= yCur * 2.0+sin(iTime) + y_border_cur * j)) {
                   frac = vec3(0, 0, 1);
               }   
           }
       }
    }
     vec2 uv3 = fragCoord/iResolution.xy-.5;
   uv3 *= .75;

  vec3 a,b,c,d;
  fractal(vec3(uv3,sin(iTime*.030)), a, 6);
  fractal(vec3(uv3,sin(iTime*.015)), b, 5);
  fractal(vec3(uv3,sin(iTime*.020)), c, 4);
    float t = iTime * .1 + ((.25 + .05 * sin(iTime * .1))/(length(uv.xy) + .07)) * 2.2;
	float si = sin(t);
	float co = cos(t);
	mat2 ma = mat2(co, si, -si, co);

    float anim = sin(iTime * 12.0) * 0.1 + 1.0;  // anim between 0.9 - 1.1 

  vec3 color = mix(c,mix(a,b,.5),.5);

    for (float i = 0.0; i < 5.0; i++) {
        uv = fract(uv * 3.5) - 0.5;
    		uv.xy *= ma;
        float d = length(uv) * exp(-length(uv0));

        vec3 col = palette(length(uv0) + i * 0.4 + iTime *1.0);

        d = sin(d * 11.0 + iTime*0.) / 8.0;
        d = abs(d);

        d = pow(0.01 / d, 2.0);

        finalColor += col * d;
    }

     fragColor= vec4(finalColor*1.*color*0.1, 1.0);
     fragColor+= vec4(happy_star(uv4, anim) * vec3(0.5,0.5,.5)*.02, 1.0);


}
